import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem91 separa RAM fisica resolucao e carga de ciclos preservando operacao',()=>{for(const [id,titulo] of [['LDzmbLcaHUVNztsXyp52',"Câmera de Segurança Wi-Fi iCSee/Yoosee A28B 4K Dupla Lente Visão Noturna Colorida Full Hd Externa Prova D'água Ip66 Sensor Movimento Woosh"],['lfGwhT6zO5b7LOPvqkuL','Smartphone Motorola Edge 60 5g - 512gb 12gb Ram+12gb Ram'],['LQ12PkH1sbM7Uu0geBQf','Lava E Seca Samsung Wd11m Com Digital Inverter Inox 11kg Cor Inox look']]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/24 GB de RAM física|4K nativo|economia garantida|impermeável/i);if(id==='LQ12PkH1sbM7Uu0geBQf'){assert.match(x.comentario,/menores que 2 kg/);assert.match(x.comentario,/menores que 1 kg/);}}});
